const draftText = drafts.map(d => `${d.key} [${d.source_method}; ${d.domain}]\nHeadline: ${d.headline}\nDerivation: ${d.derivation}\nMotivating gap: ${d.motivating_gap}\nDepth: ${d.depth}\nTest sketch: ${d.test_sketch}`).join('\n\n')

